CREATE TYPE "CrawlStatus" AS ENUM ('QUEUED','RUNNING','COMPLETED','FAILED');
CREATE TYPE "Severity" AS ENUM ('CRITICAL','WARNING','INFO');
CREATE TABLE "Crawl" ("id" TEXT PRIMARY KEY,"rootUrl" TEXT NOT NULL,"normalizedHost" TEXT NOT NULL,"status" "CrawlStatus" NOT NULL DEFAULT 'QUEUED',"progress" INTEGER NOT NULL DEFAULT 0,"processedPages" INTEGER NOT NULL DEFAULT 0,"discoveredPages" INTEGER NOT NULL DEFAULT 0,"maxPages" INTEGER NOT NULL DEFAULT 200,"statusMessage" TEXT NOT NULL DEFAULT 'Tarama sıraya alındı',"error" TEXT,"limited" BOOLEAN NOT NULL DEFAULT false,"startedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Page" ("id" TEXT PRIMARY KEY,"crawlId" TEXT NOT NULL REFERENCES "Crawl"("id") ON DELETE CASCADE,"url" TEXT NOT NULL,"statusCode" INTEGER,"contentType" TEXT,"title" TEXT,"description" TEXT,"canonical" TEXT,"robots" TEXT,"h1" JSONB,"textContent" TEXT,"contentHash" TEXT,"links" JSONB,"hreflangs" JSONB,"jsonLd" JSONB,"redirectChain" JSONB,"rendered" BOOLEAN NOT NULL DEFAULT false,"error" TEXT,"depth" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Finding" ("id" TEXT PRIMARY KEY,"crawlId" TEXT NOT NULL REFERENCES "Crawl"("id") ON DELETE CASCADE,"code" TEXT NOT NULL,"severity" "Severity" NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"recommendation" TEXT NOT NULL,"fingerprint" TEXT NOT NULL,"affectedUrls" JSONB NOT NULL,"evidence" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Exclusion" ("id" TEXT PRIMARY KEY,"crawlId" TEXT NOT NULL REFERENCES "Crawl"("id") ON DELETE CASCADE,"url" TEXT NOT NULL,"reason" TEXT NOT NULL);
CREATE UNIQUE INDEX "Page_crawlId_url_key" ON "Page"("crawlId","url"); CREATE INDEX "Crawl_normalizedHost_createdAt_idx" ON "Crawl"("normalizedHost","createdAt"); CREATE INDEX "Finding_crawlId_severity_idx" ON "Finding"("crawlId","severity"); CREATE INDEX "Finding_crawlId_code_idx" ON "Finding"("crawlId","code");
